import re

def _find_node_by_title(doc, title):
    for n in doc['nodes']:
        if n.get('title', '').strip() == title.strip():
            return n
    return None

def _find_children(doc, node):
    if 'children' in node:
        return [cid for cid in node['children'] if cid]
    return [n['node_id'] for n in doc['nodes'] if n.get('parent_id') == node['node_id']]

def _find_node_by_id(doc, nid):
    for n in doc['nodes']:
        if n['node_id'] == nid:
            return n
    return None

def _table_rows(node):
    if node.get('kind') != 'table' or 'table' not in node:
        return []
    cols = node['table']['columns']
    rows = node['table']['rows']
    return [(ri, dict(zip(cols, row))) for ri, row in enumerate(rows)]

def entities(doc, scope):
    scope_node = _find_node_by_title(doc, scope)
    if not scope_node: return []
    for cid in _find_children(doc, scope_node):
        n = _find_node_by_id(doc, cid)
        if n and n.get('kind') == 'table' and 'Products' in n.get('title', ''):
            return [{"id": row['product'], "description": f"{row['product']} ({row['group']}, {row['sub-group']}, storage {row['storage location']})"} for _, row in _table_rows(n)]
    return []

def recorded_end(doc, scope):
    scope_node = _find_node_by_title(doc, scope)
    if not scope_node: return None
    max_day = None
    for cid in _find_children(doc, scope_node):
        n = _find_node_by_id(doc, cid)
        if not n: continue
        if n.get('kind') == 'table' and 'Daily ledger' in n.get('title', ''):
            for _, row in _table_rows(n):
                d = float(row['day'])
                if max_day is None or d > max_day: max_day = d
        elif n.get('kind') == 'text':
            m = re.search(r'Days\s+\d+\s+to\s+(\d+)', n.get('text', ''))
            if m:
                d = float(m.group(1))
                if max_day is None or d > max_day: max_day = d
    return max_day

def inputs(doc, scope):
    scope_node = _find_node_by_title(doc, scope)
    if not scope_node: return []
    res = []
    for cid in _find_children(doc, scope_node):
        n = _find_node_by_id(doc, cid)
        if not n: continue
        if n.get('kind') == 'table' and 'Products' in n.get('title', ''):
            for ri, row in _table_rows(n):
                res.append({"id": f"open_{row['product']}", "time": None, "kind": "opening_stock", "entities": [row['product']], "fields": {"opening_stock": float(row['opening stock'])}, "src": [[n['node_id'], ri, ['product', 'opening stock']]]})
        elif n.get('kind') == 'table' and 'Daily ledger' in n.get('title', ''):
            for ri, row in _table_rows(n):
                day = float(row['day'])
                pid = row['product']
                res.append({"id": f"prod_{pid}_{int(day)}", "time": day, "kind": "production", "entities": [pid], "fields": {"produced": float(row['produced'])}, "src": [[n['node_id'], ri, ['day', 'product', 'produced']]]})
                res.append({"id": f"order_{pid}_{int(day)}", "time": day, "kind": "order", "entities": [pid], "fields": {"ordered": float(row['ordered'])}, "src": [[n['node_id'], ri, ['day', 'product', 'ordered']]]})
        elif n.get('kind') == 'table' and 'Order book' in n.get('title', ''):
            cols = n['table']['columns']
            for ri, row in _table_rows(n):
                if 'day placed' in cols:
                    day = float(row['day placed'])
                    pid = row['product']
                    res.append({"id": f"ob_open_{pid}_{int(day)}", "time": day, "kind": "order_book_open", "entities": [pid], "fields": {"units_open": float(row['units still open'])}, "src": [[n['node_id'], ri, ['product', 'day placed', 'units still open']]]})
                elif 'planned production' in cols:
                    day = float(row['day'])
                    pid = row['product']
                    res.append({"id": f"ob_plan_{pid}_{int(day)}", "time": day, "kind": "order_book_planned", "entities": [pid], "fields": {"planned_production": float(row['planned production']), "ordered": float(row['ordered'])}, "src": [[n['node_id'], ri, ['day', 'product', 'planned production', 'ordered']]]})
    return res

def outcomes(doc, scope):
    scope_node = _find_node_by_title(doc, scope)
    if not scope_node: return []
    res = []
    for cid in _find_children(doc, scope_node):
        n = _find_node_by_id(doc, cid)
        if not n: continue
        if n.get('kind') == 'table' and 'Daily ledger' in n.get('title', ''):
            for ri, row in _table_rows(n):
                day = float(row['day'])
                pid = row['product']
                res.append({"time": day, "kind": "shipped", "entities": [pid], "value": float(row['shipped']), "src": [[n['node_id'], ri, ['day', 'product', 'shipped']]]})
                res.append({"time": day, "kind": "backordered", "entities": [pid], "value": float(row['backordered']), "src": [[n['node_id'], ri, ['day', 'product', 'backordered']]]})
                res.append({"time": day, "kind": "stock", "entities": [pid], "value": float(row['stock']), "src": [[n['node_id'], ri, ['day', 'product', 'stock']]]})
        elif 'Events' in n.get('title', ''):
            if n.get('kind') == 'list':
                for li, line in enumerate(n.get('lines', [])):
                    line = line.strip()
                    if not line or 'No events' in line: continue
                    m = re.match(r'Day\s+(\d+)', line)
                    day = float(m.group(1)) if m else None
                    ents = list(set(re.findall(r'[A-Z]+\d+[A-Za-z0-9\-]+', line)))
                    res.append({"time": day, "kind": "event", "entities": ents, "value": None, "src": [[n['node_id'], li]]})
            elif n.get('kind') == 'text':
                for li, line in enumerate(n.get('text', '').split('\n')):
                    line = line.strip()
                    if not line or 'No events' in line: continue
                    m = re.match(r'Day\s+(\d+)', line)
                    day = float(m.group(1)) if m else None
                    ents = list(set(re.findall(r'[A-Z]+\d+[A-Za-z0-9\-]+', line)))
                    res.append({"time": day, "kind": "event", "entities": ents, "value": None, "src": [[n['node_id'], li]]})
    return res

def params(doc, scope):
    scope_node = _find_node_by_title(doc, scope)
    if not scope_node: return {}
    for cid in _find_children(doc, scope_node):
        n = _find_node_by_id(doc, cid)
        if not n: continue
        if n.get('kind') == 'text':
            m = re.search(r'Daily dispatch capacity:\s*(\d+)\s*kg', n.get('text', ''))
            if m: return {"daily_dispatch_capacity_kg": float(m.group(1))}
    return {}


