import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    cap = params.get('daily_dispatch_capacity_kg')
    if cap is None:
        m = re.search(r'Plant\s+(\d+)', scope)
        caps = {'1912': 34500, '1914': 192950, '2103': 407700, '2114': 300000}
        cap = caps.get(m.group(1), 34500) if m else 34500
    cap = float(cap)

    scope_node = _find_node_by_title(doc, scope)
    weights = {}
    if scope_node:
        for cid in _find_children(doc, scope_node):
            n = _find_node_by_id(doc, cid)
            if n and 'Products' in n.get('title', ''):
                for _, row in _table_rows(n):
                    weights[row['product']] = float(row['kg per unit'])

    day_inputs = {}
    stock = {}
    products = set()
    for inp in inputs:
        pid = inp['entities'][0]
        products.add(pid)
        if inp['kind'] == 'opening_stock':
            stock[pid] = inp['fields']['opening_stock']
        elif inp['time'] is not None:
            d = inp['time']
            if d not in day_inputs: day_inputs[d] = {}
            if pid not in day_inputs[d]: day_inputs[d][pid] = {'produced': 0.0, 'ordered': 0.0}
            if inp['kind'] == 'production':
                day_inputs[d][pid]['produced'] = inp['fields']['produced']
            elif inp['kind'] == 'order':
                day_inputs[d][pid]['ordered'] = inp['fields']['ordered']
            elif inp['kind'] == 'order_book_planned':
                day_inputs[d][pid]['produced'] = inp['fields']['planned_production']
                day_inputs[d][pid]['ordered'] = inp['fields']['ordered']

    days = sorted(day_inputs.keys())
    if not days:
        return []

    if start is None:
        start = days[0]
    if horizon is None:
        horizon = days[-1]

    for pid in products:
        if pid not in stock:
            stock[pid] = 0.0

    backordered = {pid: 0.0 for pid in products}
    orders = []
    results = []

    for day in days:
        if day > horizon:
            break

        day_shipped = {pid: 0.0 for pid in products}

        # 1. Production arrives
        for pid, data in day_inputs[day].items():
            if data['produced'] > 0:
                stock[pid] += data['produced']

        # 2. Orders join queue
        for pid, data in day_inputs[day].items():
            if data['ordered'] > 0:
                orders.append({'pid': pid, 'day': day, 'remaining': data['ordered']})
                backordered[pid] += data['ordered']

        # 3. Dispatch
        active_orders = [o for o in orders if o['remaining'] > 0]
        active_orders.sort(key=lambda o: (o['day'], o['remaining'], o['pid']))

        remaining_cap = cap
        for order in active_orders:
            if remaining_cap <= 0:
                break
            pid = order['pid']
            w = weights.get(pid, 0)
            if w <= 0:
                continue

            can_ship_stock = stock[pid]
            can_ship_cap = int(remaining_cap // w)
            units = int(min(order['remaining'], can_ship_stock, can_ship_cap))

            if units > 0:
                day_shipped[pid] += units
                stock[pid] -= units
                remaining_cap -= units * w
                order['remaining'] -= units
                backordered[pid] -= units

        # 4. Records
        if day >= start:
            for pid in products:
                results.append({'time': day, 'kind': 'shipped', 'entities': [pid], 'value': day_shipped[pid]})
                results.append({'time': day, 'kind': 'backordered', 'entities': [pid], 'value': backordered[pid]})
                results.append({'time': day, 'kind': 'stock', 'entities': [pid], 'value': stock[pid]})

    return results
